module top;
  integer sel, r;
  initial begin
    r = $fscanf(32'h8000_0000, "%d", sel);
    while (r == 1) begin
      case (sel)
        0: $display("0001");
        1: $display("0010");
        2: $display("0100");
        3: $display("1000");
        default: $display("0000");
      endcase
      r = $fscanf(32'h8000_0000, "%d", sel);
    end
    $finish;
  end
endmodule
